    with open(p) as f:
        for line in f:
            if line.startswith('#'): continue
            cols=line.rstrip('\\n').split('\\t')
            if len(cols)>=2:
                status=cols[1]
                if status=='Complete': complete.append(cols[0])
                elif status=='Duplicated': dup.append(cols[0])
                elif status=='Fragmented': frag.append(cols[0])
                elif status=='Missing': miss.append(cols[0])
    print('Complete',len(complete),'unique',len(set(complete)),'Duplicated rows',len(dup),'Fragmented',len(frag),'Missing',len(miss))
